$ErrorActionPreference='Stop'
$base=Split-Path $PSScriptRoot -Parent
Add-Type -AssemblyName UIAutomationClient,UIAutomationTypes
Add-Type -Path (Join-Path $PSScriptRoot 'native-ui.cs')
function Click($h){[SmokeWindows]::PostMessage($h,0xF5,[IntPtr]::Zero,[IntPtr]::Zero)|Out-Null}
function Window($process,$class,$title){for($i=0;$i -lt 100;$i++){foreach($h in [SmokeWindows]::ForProcess($process.Id)){if([SmokeWindows]::Class($h) -like $class -and [SmokeWindows]::Text($h) -like $title){return $h}};Start-Sleep -Milliseconds 100};throw "Missing $class $title"}
function Button($window,$label){$h=[SmokeWindows]::Children($window)|Where-Object{[SmokeWindows]::Text($_) -eq $label}|Select-Object -First 1;if(!$h){throw "Missing button $label"};return $h}
function FileDialog($process,$path){Write-Host "Selecting $path";$d=Window $process '#32770' '*';Start-Sleep -Milliseconds 300;$a=[Windows.Automation.AutomationElement]::FromHandle($d);$ed=$a.FindAll([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.Condition]::TrueCondition)|Where-Object{$_.Current.ControlType -eq [Windows.Automation.ControlType]::Edit -and ($_.Current.AutomationId -eq '1148' -or $_.Current.Name -like '*文件名*')}|Select-Object -Last 1;if($ed){$ed.GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).SetValue($path)}else{$edit=[SmokeWindows]::Children($d)|Where-Object{[SmokeWindows]::Class($_) -eq 'Edit' -and [SmokeWindows]::GetDlgCtrlID($_) -eq 1148}|Select-Object -First 1;if(!$edit){$edit=[SmokeWindows]::Children($d)|Where-Object{[SmokeWindows]::Class($_) -eq 'Edit'}|Select-Object -First 1};if(!$edit){Write-Host ([SmokeWindows]::Text($d));[SmokeWindows]::Children($d)|ForEach-Object{Write-Host ([SmokeWindows]::Class($_)) ([SmokeWindows]::Text($_))};throw 'Filename edit missing'};[SmokeWindows]::SendMessage($edit,0xC,[IntPtr]::Zero,$path)|Out-Null};$ok=[SmokeWindows]::Children($d)|Where-Object{[SmokeWindows]::GetDlgCtrlID($_) -eq 1 -and [SmokeWindows]::Class($_) -eq 'Button'}|Select-Object -First 1;Click $ok;Start-Sleep -Milliseconds 400}
